// Append the Official n8n Core Test Workflows & Fixtures from n8n-master
export const N8N_TEST_SEEDS: TemplateSeed[] = OFFICIAL_N8N_TEST_FLOWS.map((flow) => ({
  id: flow.id,
  name: flow.name,
  description: flow.description,
  category: 'n8n Core Test Fixtures' as TemplateCategory,
  vertical: 'Core Testing & QA',
  targetOutcome: `Official test fixture (${flow.sourceFixture})`,
  tags: ['n8n-test', 'official-fixture', flow.category.toLowerCase()],
  rawN8n: flow.n8nJson as unknown as RawN8nWorkflow,
}));

TEMPLATE_SEEDS.push(...N8N_TEST_SEEDS);

const hydratedCache = new Map<string, WorkflowTemplate>();

/**
 * Hydrates a TemplateSeed through the Universal n8n Adapter (with Kahn's topological layout
 * and missing credentials analysis).
 */
export function hydrateTemplate(seed: TemplateSeed): WorkflowTemplate {
  const cached = hydratedCache.get(seed.id);
  if (cached) return cached;

  const parsed = parseN8nWorkflow(seed.rawN8n);
  const hydrated: WorkflowTemplate = {
    id: seed.id,
    name: seed.name,
    description: seed.description,
    category: seed.category,
    vertical: seed.vertical,
    targetOutcome: seed.targetOutcome,
    tags: seed.tags,
    requiredCredentials: parsed.missingCredentials.map((c) => c.envVarName),
    nodes: parsed.nodes,
    edges: parsed.edges,
    rawN8nJson: seed.rawN8n as unknown as Record<string, unknown>,
    isPublic: true,
  };

  hydratedCache.set(seed.id, hydrated);
  return hydrated;
}

/**
 * Returns all 120+ built-in production templates hydrated and ready for the canvas.
 */
export function getAllTemplates(): WorkflowTemplate[] {
  return TEMPLATE_SEEDS.map(hydrateTemplate);
}

/**
 * Searches and filters templates by query string, category, or vertical.
 */
export function searchTemplates(options: {
  query?: string;
  category?: string | null;
  vertical?: string | null;
}): WorkflowTemplate[] {
  const q = (options.query || '').trim().toLowerCase();
  const cat = options.category;
  const vert = options.vertical;

  return TEMPLATE_SEEDS.filter((seed) => {
    if (cat && cat !== 'All' && seed.category.toLowerCase() !== cat.toLowerCase()) {
      return false;
    }
    if (vert && seed.vertical.toLowerCase() !== vert.toLowerCase()) {
      return false;
    }
    if (!q) return true;
    return (
      seed.name.toLowerCase().includes(q) ||
      seed.description.toLowerCase().includes(q) ||
      seed.vertical.toLowerCase().includes(q) ||
      seed.tags.some((t) => t.toLowerCase().includes(q))
    );
  }).map(hydrateTemplate);
}

export function getTemplateById(id: string): WorkflowTemplate | undefined {
  const seed = TEMPLATE_SEEDS.find((s) => s.id === id);
  return seed ? hydrateTemplate(seed) : undefined;
}
